  intdelay_process : PROCESS (clk)
  BEGIN
    IF clk'EVENT AND clk = '1' THEN
      IF reset = '1' THEN
        intdelay_reg <= (OTHERS => '0');
      ELSIF enb = '1' THEN
        IF syncReset = '1' THEN
          intdelay_reg <= (OTHERS => '0');
        ELSIF dinRegVld = '1' THEN
          intdelay_reg(0) <= dinRegVld;
          intdelay_reg(38 DOWNTO 1) <= intdelay_reg(37 DOWNTO 0);
        END IF;
      END IF;
    END IF;
  END PROCESS intdelay_process;

  vldShift <= intdelay_reg(38);

  vldOutTmp <= dinRegVld AND vldShift;

  ZERO_OUT <= to_signed(16#00000#, 18);

  addin <= to_signed(0, 48);

  tapout_signed <= signed(tapout_34);

  dout_cast <= tapout_signed(38 DOWNTO 21);

  
